 void forgedPdf()throws Exception{byte[] original=convert("text.pdf");Map<String,byte[]> files=new LinkedHashMap<>();try(ZipInputStream zip=new ZipInputStream(new ByteArrayInputStream(original))){ZipEntry e;while((e=zip.getNextEntry())!=null)files.put(e.getName(),PersonalDocuments.read(zip,PersonalDocuments.MAX_INPUT,()->false));}String text=new String(files.get("text.txt"),StandardCharsets.UTF_8).replace("Amethyst","Zirconxx");files.put("text.txt",b(text));JSONObject m=new JSONObject(new String(files.get("personal.json"),StandardCharsets.UTF_8));m.put("text_sha256",KnowledgePack.hash(b(text)));JSONArray spans=m.getJSONArray("passages");for(int i=0;i<spans.length();i++){JSONObject span=spans.getJSONObject(i);span.put("sha256",KnowledgePack.hash(b(text.substring(span.getInt("start"),span.getInt("end")))));}files.put("personal.json",b(m.toString()));ByteArrayOutputStream output=new ByteArrayOutputStream();try(ZipOutputStream zip=new ZipOutputStream(output)){for(String key:files.keySet())PersonalDocuments.put(zip,key,files.get(key));}reject(()->KnowledgePack.read(new ByteArrayInputStream(output.toByteArray()),true),"forged_pdf_text_with_recomputed_hashes_rejected");}
